parameters.jsCode:
return items.map(item => ({
  json: {
    content: [
      item.json.descricao,
      item.json.marca,
      item.json.grupo,
      item.json.sub_grupo,
      item.json.item,
      item.json.tipo
    ].filter(v => v && v !== 'NAO USA').join(' '),
    metadata: {
      codigo_produto: item.json.codigo_produto,
      descricao:   item.json.descricao,
      marca:       item.json.marca,
      grupo:       item.json.grupo,
      sub_grupo:   item.json.sub_grupo,
      item:        item.json.item,
      preco_venda: item.json.preco_venda,
      qtd_estoque: item.json.qtd_estoque
    }
  }
}));

