DELETE FROM sync_fila
WHERE codigo_produto IN (
  SELECT codigo_produto FROM sync_fila LIMIT 500
);

UPDATE sync_controle 
SET ultima_sync = NOW(),
    total_processados = (SELECT COUNT(*) FROM estoque_vetores)
WHERE id = (SELECT MAX(id) FROM sync_controle);

SELECT 1 AS ok;

DELETE FROM sync_fila
WHERE codigo_produto IN (
  SELECT sf.codigo_produto 
  FROM sync_fila sf
  INNER JOIN estoque_vetores ev 
    ON ev.metadata->'metadata'->>'codigo_produto' = sf.codigo_produto
);

SELECT 1 AS ok;
